class MyCircularQueue:
    def __init__(self, k):
        self.q=[0]*k
        self.head=0
        self.count=0
        self.size=k

    def enQueue(self,value):
        if self.count==self.size:
            return False
        tail=(self.head+self.count)%self.size
        self.q[tail]=value
        self.count+=1
        return True

    def deQueue(self):
        if self.count==0:
            return False
        self.head=(self.head+1)%self.size
        self.count-=1
        return True

    def Front(self):
        return -1 if self.count==0 else self.q[self.head]

    def Rear(self):
        if self.count==0: return -1
        return self.q[(self.head+self.count-1)%self.size]

    def isEmpty(self): return self.count==0

    def isFull(self): return self.count==self.size

