def openLock(deadends,target):
    dead=set(deadends)
    if '0000' in dead:
        return -1

    q=deque([('0000',0)])
    seen={'0000'}

    while q:
        node,steps=q.popleft()

        if node==target:
            return steps

        for i in range(4):
            digit=int(node[i])

            for move in (-1,1):
                nd=(digit+move)%10
                nxt=node[:i]+str(nd)+node[i+1:]

                if nxt not in seen and nxt not in dead:
                    seen.add(nxt)
                    q.append((nxt,steps+1))

    return -1

